# perf-tb16 tbench half: settings and helpers shared by every script (sourced, never run).
# The deployed root is the directory above bin/ (/home/ubuntu/tb16, a NEW directory next to the SWE halves
# /home/ubuntu/swe10, swe16, swe32 and perf-gemma0's /home/ubuntu/gemma0, which are never written by this half except
# through their own lock protocol: lockset.py takes their tbench locks with byte-identical copies of their lock
# modules). tb16.env (generated by build.py, deployed by deploy_tbench.ps1) names the Harbor env, the host python,
# the task cache, the host limits and the shared lock roots.
TB16_BIN=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
TB16_ROOT=${TB16_ROOT:-$(dirname "$TB16_BIN")}
if [[ -f $TB16_ROOT/tb16.env ]]; then
  # shellcheck disable=SC1091
  . "$TB16_ROOT/tb16.env"
fi
HOST_PYTHON=${HOST_PYTHON:-/usr/bin/python3}
export TB16_SHARED_LOCKS
RUNS=$TB16_ROOT/runs
SOCKS=$TB16_ROOT/sock
PACKAGES=$TB16_ROOT/packages
RUN_ID_RE='^[A-Za-z0-9_.-]{1,80}$'
LABEL_RE='^[a-z][a-z0-9-]{0,15}$'

hpy() { "$HOST_PYTHON" -I -B "$@"; }
locks() { TB16_SHARED_LOCKS="$TB16_SHARED_LOCKS" hpy "$TB16_BIN/lockset.py" "$TB16_ROOT" "$@"; }
json_line() {  # json_line <event> <extra JSON object>: one final JSON line
  hpy -c 'import json,sys; v=json.loads(sys.argv[2]); v["event"]=sys.argv[1]; print(json.dumps(v, sort_keys=True))' "$1" "$2"
}
